R=Path('/evidence/extended/helper-toolbar-work/safari-right-circle-round');F=R/'a-proposed';O=Path('/evidence/extended/safari-bag-primary-input');case=json.loads((F/'case.json').read_text());T=np.array(Image.open(F/'target.png'));A=np.array(Image.open('/evidence/apple-matches/219-290.png'));controls=np.load(R/'source-controls.npz');print('CONTROL_KEYS',controls.files,flush=True)
