report={'case_sha256':hashlib.sha256(json.dumps(case,sort_keys=True).encode()).hexdigest(),'source_PNG_exact_quadratic_and_quantization':True,'source_and_target_hashes_exact':True,'pinned_module_blob_and_SVG_hashes_exact':True,'same_219_290_pixels_as_other_intakes':bool(np.array_equal(T,A)),'other_intake_max_pixel_difference':int(np.max(abs(T.astype(int)-A.astype(int)))),'hidden_observed_fraction':0,'count':0,'input_only':True,'limits':'Pose ridgep95~2px and lower source controls2.273levels; actual footprint/lighting and exact glyph variant uncertain. Estimated RGB only.'};(O/'verification.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
